"""Restores original readable colour code only. No ZIP needed.
Run once from the folder containing app.py.
"""
from pathlib import Path
import base64
from datetime import datetime

ROOT = Path(__file__).resolve().parent
FILES = {
    'styles.py': '',
    'pages/report.py': '',
    'pages/medicine.py': '',
    'pages/home.py': '',
    'pages/dashboard.py': '',
    'components/sidebar.py': '',
    'components/hero.py': '',
    'components/cards.py': '',
}

backup = ROOT / ("colour_backup_" + datetime.now().strftime("%Y%m%d_%H%M%S"))
restored = []
for relative, encoded in FILES.items():
    target = ROOT / relative
    if not target.parent.exists():
        print(f"Skipped (folder not found): {relative}")
        continue
    if target.exists():
        saved = backup / relative
        saved.parent.mkdir(parents=True, exist_ok=True)
        saved.write_bytes(target.read_bytes())
    target.write_bytes(base64.b64decode(encoded))
    restored.append(relative)

print("Restored original, readable colours in:")
print("\n".join(restored))
print(f"Backup of your current files: {backup.name}")
